    "Le tue creazioni restano tue. Senza il tuo consenso, FORi Flower non le pubblicherà né le userà per promozioni o prodotti.",
    "Suas criações pertencem a você. FORi Flower não as publicará nem as usará para divulgação ou produtos sem o seu consentimento.",
    "Ваши творения принадлежат вам. FORi Flower не будет публиковать их, использовать в рекламе или изготовлении товаров без вашего согласия."
