  "裁切作品 · 4:6": [
    "Crop artwork · 4:6",
    "作品をトリミング · 4:6",
    "작품 자르기 · 4:6",
    "Recadrer la création · 4:6",
    "Werk zuschneiden · 4:6",
    "Recortar creación · 4:6",
    "Ritaglia creazione · 4:6",
    "Recortar criação · 4:6",
    "Обрезка работы · 4:6"
  ],
  "先確認賀卡文字已清除，花藝與品牌標誌完整保留，再拖曳圖片，將主要花朵放在畫面中央；也可以縮小圖片，空白處會補上底色。原始投稿圖片會保留，確認後才會上架。": [
    "First remove greeting text while preserving the flowers and logo. Drag to center the main flowers, or zoom out to fill empty areas with the background color. The original submission is retained. Publication happens only after confirmation.",
    "カードの文字を消し、花とブランドロゴを残したことを確認してください。画像をドラッグして主な花を中央に配置します。縮小した余白には背景色が入ります。原画像は保持され、確認後に公開されます。",
    "카드 문구를 지우고 꽃과 브랜드 로고를 온전히 남긴 뒤 이미지를 드래그해 주요 꽃을 중앙에 놓으세요. 축소한 빈 공간은 배경색으로 채워집니다. 원본은 보존되며 확인 후 공개됩니다.",
    "Vérifiez que le texte de la carte est effacé et que les fleurs et le logo restent entiers. Glissez l’image pour centrer les fleurs principales ou réduisez-la : les espaces seront remplis avec la couleur de fond. L’original est conservé ; la publication nécessite votre confirmation.",
    "Prüfe, ob der Kartentext entfernt und Blumen und Logo vollständig erhalten sind. Ziehe die Hauptblumen in die Bildmitte oder verkleinere das Bild; freie Flächen werden mit der Hintergrundfarbe gefüllt. Das Original bleibt erhalten. Veröffentlicht wird erst nach Bestätigung.",
    "Primero comprueba que se haya borrado el texto de la tarjeta y que el arreglo y el logotipo estén completos. Arrastra la imagen para centrar las flores principales; también puedes reducirla y rellenar el espacio con el color de fondo. Se conserva el original y solo se publica tras confirmar.",
    "Verifica che il testo sia rimosso e che fiori e logo siano integri. Trascina l’immagine per centrare i fiori principali oppure riducila: gli spazi vuoti verranno riempiti con il colore di fondo. L’originale resta salvato; la pubblicazione avviene solo dopo conferma.",
    "Primeiro confira se o texto do cartão foi removido e se o arranjo e o logotipo estão completos. Arraste a imagem para centralizar as flores principais; você também pode reduzi-la e preencher o espaço com a cor de fundo. O original é preservado e a publicação só ocorre após a confirmação.",
    "Убедитесь, что текст открытки удалён, а цветы и логотип сохранены целиком. Перетащите изображение, поместив основные цветы в центр. При уменьшении пустоты заполняются фоном. Оригинал сохраняется; публикация выполняется после подтверждения."
  ],
