  "每個人，都值得被看見": [
    "Everyone deserves to be seen",
    "誰もが、見てもらう価値がある",
    "모든 사람은 주목받을 가치가 있어요",
    "Chacun mérite d’être vu",
    "Jeder Mensch verdient es, gesehen zu werden",
    "Todos merecemos ser vistos",
    "Ognuno merita di essere visto",
    "Todos merecem ser vistos",
    "Каждый заслуживает быть замеченным"
  ],
  "創作是自由的，每一種感受都值得被看見。遊戲也能是一種藝術，讓我們在遊玩之中感受、表達，留下自己的作品。": [
    "Creativity is free, and every feeling deserves to be seen. Games can be art too, letting us feel, express ourselves and create something of our own through play.",
    "創作は自由。どんな気持ちも見てもらう価値があります。ゲームも芸術のひとつ。遊びながら感じ、表現し、自分の作品を残せます。",
    "창작은 자유롭고 모든 감정은 존중받을 가치가 있습니다. 게임도 예술이 될 수 있습니다. 즐기며 느끼고 표현하며 나만의 작품을 남겨 보세요.",
    "La création est libre et chaque ressenti mérite d’être vu. Le jeu peut aussi être un art : il nous permet de ressentir, de nous exprimer et de créer nos propres œuvres.",
    "Kreativität ist frei, und jedes Gefühl verdient es, gesehen zu werden. Auch Spielen kann Kunst sein: Wir fühlen, drücken uns aus und erschaffen eigene Werke.",
    "Crear es libre, y cada sentimiento merece ser visto. Los juegos también pueden ser arte: al jugar, sentimos, nos expresamos y dejamos nuestras propias creaciones.",
    "La creatività è libera e ogni emozione merita di essere vista. Anche il gioco può essere arte: ci permette di sentire, esprimerci e lasciare le nostre creazioni.",
    "Criar é livre, e cada sentimento merece ser visto. Jogos também podem ser arte: ao brincar, sentimos, nos expressamos e deixamos nossas próprias criações.",
    "Творчество свободно, и каждое чувство заслуживает быть замеченным. Игра тоже может быть искусством: в ней мы чувствуем, выражаем себя и создаём свои работы."
  ],
  "藝術是自由的，不分高低。選一個顏色、調整一朵花的位置，就能體驗純粹的創作樂趣。每個人的感受，都值得被看見。": [
    "Art is free, without hierarchy. Choose a color or move a flower to experience the simple joy of creating. Everyone's feelings deserve to be seen.",
    "芸術は自由で、優劣はありません。色を選び、花の位置を調整するだけで、純粋な創作の楽しさを味わえます。一人ひとりの気持ちに価値があります。",
    "예술은 자유로우며 우열이 없습니다. 색을 고르고 꽃의 위치를 바꾸는 것만으로도 순수한 창작의 즐거움을 느낄 수 있습니다. 모든 사람의 감정은 존중받을 가치가 있습니다.",
    "L’art est libre, sans hiérarchie. Choisir une couleur ou déplacer une fleur suffit pour goûter au plaisir de créer. Le ressenti de chacun mérite d’être vu.",
    "Kunst ist frei, ohne Rangordnung. Eine Farbe wählen oder eine Blume verschieben genügt, um die Freude am Gestalten zu erleben. Jedes Gefühl verdient es, gesehen zu werden.",
    "El arte es libre, sin jerarquías. Elegir un color o mover una flor basta para vivir la alegría de crear. Los sentimientos de cada persona merecen ser vistos.",
    "L’arte è libera, senza gerarchie. Scegliere un colore o spostare un fiore basta per provare il piacere di creare. Le emozioni di ognuno meritano di essere viste.",
    "A arte é livre, sem hierarquias. Escolher uma cor ou mover uma flor basta para sentir a alegria de criar. Os sentimentos de cada pessoa merecem ser vistos.",
    "Искусство свободно и не делится на высшее и низшее. Выберите цвет, передвиньте цветок — и почувствуйте чистую радость творчества. Чувства каждого заслуживают внимания."
  ],
  "把美好傳給你重視的人": [
    "Share something lovely with someone you care about",
    "大切な人に美しさを届ける",
    "소중한 사람에게 아름다움을 전하세요",
    "Partagez la beauté avec ceux qui comptent",
    "Schenke den Menschen, die dir wichtig sind, etwas Schönes",
    "Comparte belleza con quienes te importan",
    "Condividi la bellezza con chi conta per te",
    "Compartilhe beleza com quem importa para você",
    "Поделитесь прекрасным с близкими"
  ],
  "把作品分享給朋友，或印成小卡、寫下一句話。讓微小的美好與幸福，從你的手裡傳出去。": [
    "Share your creation with a friend, or print a little card and add a message. Pass on a small moment of beauty and happiness.",
    "作品を友達に送ったり、小さなカードに印刷して言葉を添えたり。小さな美しさと幸せを、あなたの手から届けましょう。",
    "작품을 친구에게 보내거나 작은 카드로 인쇄해 한마디를 적어 보세요. 작은 아름다움과 행복을 여러분의 손으로 전하세요.",
    "Partagez votre création, imprimez une carte et ajoutez quelques mots. Faites circuler ces petits instants de beauté et de bonheur.",
    "Teile dein Werk oder drucke eine kleine Karte und schreibe ein paar Worte dazu. Gib kleine Momente der Schönheit und Freude weiter.",
    "Comparte tu creación con amigos o imprímela como una tarjeta con unas palabras. Deja que pequeños momentos de belleza y alegría salgan de tus manos.",
    "Condividi la creazione o stampala su un biglietto e aggiungi qualche parola. Fai viaggiare piccoli momenti di bellezza e felicità.",
    "Compartilhe sua criação com amigos ou imprima um cartão com algumas palavras. Deixe que pequenos momentos de beleza e alegria saiam das suas mãos.",
    "Отправьте работу другу или напечатайте её на карточке и добавьте несколько слов. Пусть маленькая красота и радость передаются из ваших рук."
  ],
