    "Schreibe einem Freund ein paar Worte oder stelle eine Karte auf den Tisch, um deine Lieblingswerke zu bewahren.",
    "Escribe unas palabras para un amigo o deja una tarjeta junto a tu mesa para conservar tu creación favorita.",
