  "選「下載明信片用檔案」。檔案為 3240 × 4860 像素、4 × 6 比例，花與文字完整保留。": [
    "Select Download postcard file. The 3240 × 4860 pixel file uses a 4:6 ratio and preserves all flowers and text.",
    "「ポストカード用ファイルをダウンロード」を選びます。3240 × 4860ピクセル、比率4 × 6で、花と文字がすべて保存されます。",
    "‘엽서용 파일 다운로드’를 선택하세요. 3240 × 4860픽셀, 4 × 6 비율로 꽃과 글자가 모두 보존됩니다.",
    "Choisissez « Télécharger le fichier pour carte postale ». Le fichier mesure 3240 × 4860 pixels au format 4 × 6 et conserve intégralement fleurs et texte.",
    "Wähle „Postkartendatei herunterladen“. Die Datei hat 3240 × 4860 Pixel im Verhältnis 4 × 6; Blumen und Text bleiben vollständig erhalten.",
    "Elige «Descargar archivo para postal». El archivo tiene 3240 × 4860 píxeles y proporción 4 × 6; conserva todas las flores y el texto.",
    "Scegli «Scarica file per cartolina». Il file è di 3240 × 4860 pixel, in proporzione 4 × 6, e conserva tutti i fiori e il testo.",
    "Escolha «Baixar arquivo para cartão-postal». O arquivo tem 3240 × 4860 pixels e proporção 4 × 6; preserva todas as flores e o texto.",
    "Выберите «Скачать файл для открытки». Файл размером 3240 × 4860 пикселей с пропорциями 4 × 6 сохраняет все цветы и текст."
  ],
  "iPhone 可在「檔案 → 下載項目」找到圖片；Android 可在「下載」找到。上傳時選擇這張原圖，避免使用截圖或通訊軟體壓縮過的圖片。": [
    "On iPhone, find the image in Files → Downloads; on Android, in Downloads. Upload the original file rather than a screenshot or an image compressed by a messaging app.",
    "iPhoneでは「ファイル → ダウンロード」、Androidでは「ダウンロード」に保存されます。アップロードには原画像を使い、スクリーンショットやメッセージアプリで圧縮した画像は避けてください。",
    "iPhone은 ‘파일 → 다운로드’, Android는 ‘다운로드’에서 찾을 수 있습니다. 스크린샷이나 메신저로 압축된 이미지 대신 이 원본을 업로드하세요.",
    "Sur iPhone, l’image se trouve dans Fichiers → Téléchargements ; sur Android, dans Téléchargements. Importez l’original plutôt qu’une capture ou une image compressée par une messagerie.",
    "Auf dem iPhone findest du das Bild unter Dateien → Downloads, auf Android unter Downloads. Lade das Original hoch, keinen Screenshot und kein durch Messenger komprimiertes Bild.",
    "En iPhone, busca la imagen en Archivos → Descargas; en Android, en Descargas. Sube el original, no capturas de pantalla ni imágenes comprimidas por aplicaciones de mensajería.",
    "Su iPhone trovi l’immagine in File → Download; su Android in Download. Carica l’originale, evitando schermate o immagini compresse dalle app di messaggistica.",
    "No iPhone, encontre a imagem em Arquivos → Downloads; no Android, em Downloads. Envie o original, não capturas de tela nem imagens comprimidas por aplicativos de mensagens.",
    "На iPhone файл находится в «Файлы → Загрузки», на Android — в «Загрузки». Загружайте оригинал, а не снимок экрана или изображение, сжатое мессенджером."
  ],
