    "Tap ☆ to favorite a work. It will appear first and larger, only in your own flower room.",
    "☆でお気に入りを付けると、先頭に大きく表示されます。変更は自分の花室だけに反映されます。",
    "☆로 즐겨찾기하면 앞쪽에 크게 표시됩니다. 자신의 꽃방에만 적용됩니다.",
    "Marquez vos favoris avec ☆ : ils apparaîtront d’abord et en plus grand. Cela concerne uniquement votre atelier.",
