  "以黃色為起點。看花朵、葉片與花器，如何承接一束光。": [
    "Start with yellow. See how flowers, leaves, and vessels catch a ray of light.",
    "黄色を出発点に。花、葉、花器が一筋の光を受け止める様子を見てみましょう。",
    "노란색에서 시작합니다. 꽃, 잎, 화기가 한 줄기 빛을 어떻게 담는지 살펴보세요.",
    "Partir du jaune. Observer comment fleurs, feuilles et vases accueillent un rayon de lumière.",
    "Mit Gelb beginnen. Entdecke, wie Blüten, Blätter und Gefäße einen Lichtstrahl aufnehmen.",
    "Empieza con el amarillo. Observa cómo flores, hojas y recipientes reciben un rayo de luz.",
    "Partire dal giallo. Osserva come fiori, foglie e vasi accolgono un raggio di luce.",
    "Comece com o amarelo. Observe como flores, folhas e recipientes acolhem um raio de luz.",
    "Начните с жёлтого. Посмотрите, как цветы, листья и ваза принимают луч света."
  ],
  "留白": [
    "Space",
    "余白",
    "여백",
    "L’espace libre",
    "Freiraum",
    "Espacio en blanco",
    "Spazio vuoto",
    "Espaço em branco",
    "Свободное пространство"
  ],
  "花與花之間，也有風景。慢一點看線條、方向，以及沒有放滿的空間。": [
    "There is a landscape between flowers, too. Slow down and notice the lines, directions, and spaces left unfilled.",
    "花と花の間にも景色があります。線や向き、満たされていない空間をゆっくり眺めて。",
    "꽃과 꽃 사이에도 풍경이 있습니다. 선과 방향, 채우지 않은 공간을 천천히 살펴보세요.",
    "Entre les fleurs aussi, un paysage se dessine. Prenez le temps d’observer les lignes, les directions et les espaces laissés libres.",
    "Auch zwischen den Blumen liegt eine Landschaft. Betrachte in Ruhe Linien, Richtungen und den freigelassenen Raum.",
    "También hay paisajes entre las flores. Mira con calma las líneas, las direcciones y los espacios que quedan libres.",
    "Anche tra i fiori c’è un paesaggio. Osserva con calma le linee, le direzioni e gli spazi lasciati vuoti.",
    "Também há paisagens entre as flores. Observe com calma as linhas, as direções e os espaços que ficam livres.",
    "Между цветами тоже есть пейзаж. Рассмотрите линии, направления и незаполненное пространство, не спеша."
  ],
  "色彩研究：紅": [
    "Color Study: Red",
    "色彩研究：赤",
    "색채 연구: 빨강",
    "Étude de couleur : rouge",
    "Farbstudie: Rot",
    "Estudio de color: rojo",
    "Studio del colore: rosso",
    "Estudo de cor: vermelho",
    "Исследование цвета: красный"
  ],
  "從酒紅、玫瑰紅到淡粉。把不同的花，放進同一場色彩對話。": [
    "From burgundy and rose red to pale pink. Bring different flowers into a shared conversation in color.",
    "ワインレッドからローズ、淡いピンクまで。異なる花を、ひとつの色の対話に。",
    "와인색부터 장미빛 빨강, 연분홍까지. 서로 다른 꽃을 하나의 색채 대화 안에 놓아 보세요.",
    "Du bordeaux au rouge rose et au rose pâle. Réunir différentes fleurs dans un même dialogue de couleurs.",
    "Von Weinrot über Rosenrot bis zu zartem Rosa. Lass unterschiedliche Blumen einen gemeinsamen Farbdialog führen.",
    "Del burdeos al rojo rosa y al rosa pálido. Reúne flores distintas en una misma conversación de color.",
    "Dal bordeaux al rosso rosa fino al rosa pallido. Riunisci fiori diversi in un unico dialogo di colori.",
    "Do bordô ao vermelho-rosa e ao rosa-claro. Reúna flores diferentes numa mesma conversa de cores.",
    "От винного и розово-красного до нежно-розового. Объедините разные цветы в одном разговоре о цвете."
  ],
