Object.assign(globalThis.ForiLocaleExtra,{"萬聖節": ["Halloween", "ハロウィン", "할로윈", "Halloween", "Halloween", "Halloween", "Halloween", "Halloween", "Хэллоуин"], "南瓜花器": ["Pumpkin vase", "かぼちゃの花器", "호박 화병", "Vase citrouille", "Kürbisvase", "Jarrón de calabaza", "Vaso a zucca", "Vaso de abóbora", "Ваза-тыква"], "狗頭骨花器": ["Dog skull vase", "犬の頭骨の花器", "개 두개골 화병", "Vase crâne de chien", "Hundeschädel-Vase", "Jarrón de cráneo de perro", "Vaso a teschio di cane", "Vaso de crânio de cão", "Ваза в форме черепа собаки"], "南瓜橘": ["Pumpkin orange", "パンプキンオレンジ", "호박 주황", "Orange citrouille", "Kürbisorange", "Naranja calabaza", "Arancione zucca", "Laranja abóbora", "Тыквенный оранжевый"], "霜白色": ["Frost white", "フロストホワイト", "서리빛 흰색", "Blanc givré", "Frostweiß", "Blanco escarcha", "Bianco ghiaccio", "Branco gelo", "Морозный белый"]});

Object.assign(globalThis.ForiLocaleExtra,{"創作是自由的，每一種感受都值得被看見。": ["Creation is free. Every feeling deserves to be seen.", "創作は自由です。どんな気持ちも、大切に受けとめられる価値があります。", "창작은 자유로워요. 모든 감정은 존중받을 가치가 있어요.", "La création est libre. Chaque ressenti mérite d’être vu.", "Kreativität ist frei. Jedes Gefühl verdient es, gesehen zu werden.", "Crear es un acto de libertad. Cada sentimiento merece ser visto.", "Creare è libertà. Ogni emozione merita di essere vista.", "Criar é um ato de liberdade. Cada sentimento merece ser visto.", "Творчество свободно. Каждое чувство заслуживает внимания."], "選一個顏色，調整一朵花的位置，在遊玩之中感受、表達，留下自己的作品。遊戲也能是一種藝術，讓我們體驗純粹的創作樂趣。": ["Choose a color, move a flower, and explore what you feel as you play. Express yourself and leave with a creation of your own. Games can be art, too—a way to experience the simple joy of creating.", "色を選び、花の位置を少し動かす。遊びながら感じたことを表現し、自分だけの作品を残しましょう。ゲームもひとつのアートとして、創作する純粋な楽しさを届けてくれます。", "색을 고르고 꽃의 위치를 옮기며, 놀이 속에서 느끼고 표현하고 나만의 작품을 남겨 보세요. 게임도 하나의 예술이 되어 창작의 순수한 즐거움을 전할 수 있어요.", "Choisissez une couleur, déplacez une fleur et laissez le jeu vous inviter à ressentir, à vous exprimer et à créer une œuvre qui vous ressemble. Le jeu peut aussi être un art, une façon de goûter au simple plaisir de créer.", "Wähle eine Farbe, verschiebe eine Blume und entdecke beim Spielen, was du fühlst. Drücke dich aus und erschaffe dein eigenes Werk. Auch Spiele können Kunst sein und die reine Freude am Gestalten vermitteln.", "Elige un color, cambia una flor de lugar y siente y exprésate mientras juegas, dejando una creación propia. Los juegos también pueden ser arte y acercarnos al simple placer de crear.", "Scegli un colore, sposta un fiore e lascia che il gioco ti aiuti a sentire, esprimerti e creare un’opera tutta tua. Anche il gioco può essere arte, un modo per assaporare la semplice gioia di creare.", "Escolha uma cor, mude uma flor de lugar e sinta e se expresse enquanto brinca, deixando uma criação sua. Os jogos também podem ser arte e nos aproximar da alegria simples de criar.", "Выберите цвет, передвиньте цветок и позвольте игре помочь вам почувствовать, выразить себя и создать собственную работу. Игра тоже может быть искусством и дарить простую радость творчества."], "把作品分享給朋友，或印成小卡，寫下一句話。讓微小的美好與幸福，從你的手裡傳給重視的人。": ["Share your creation with a friend, or print it as a little card and add a few words. Let a small moment of beauty and happiness travel from your hands to someone you care about.", "作品を友達にシェアしたり、小さなカードに印刷して言葉を添えたり。ささやかな美しさと幸せを、あなたの手から大切な人へ届けてみませんか。", "작품을 친구에게 공유하거나 작은 카드로 인쇄해 한마디를 적어 보세요. 소소한 아름다움과 행복이 당신의 손에서 소중한 사람에게 전해지도록요.", "Partagez votre création avec un ami, ou imprimez-la sur une petite carte et ajoutez quelques mots. Faites passer un peu de beauté et de bonheur de vos mains à une personne qui vous est chère.", "Teile dein Werk mit Freunden oder drucke es als kleine Karte aus und schreibe ein paar Worte dazu. So gelangen kleine Momente voller Schönheit und Glück aus deinen Händen zu Menschen, die dir wichtig sind.", "Comparte tu obra con un amigo, o imprímela como una pequeña tarjeta y añade unas palabras. Deja que un poco de belleza y felicidad llegue desde tus manos a alguien que te importa.", "Condividi la tua creazione con un amico, oppure stampala su un biglietto e aggiungi qualche parola. Lascia che un piccolo momento di bellezza e felicità passi dalle tue mani a una persona cara.", "Compartilhe sua criação com um amigo, ou imprima um pequeno cartão e acrescente algumas palavras. Deixe um pouco de beleza e felicidade chegar, pelas suas mãos, a alguém importante para você.", "Поделитесь работой с другом или напечатайте её на небольшой открытке и добавьте пару слов. Пусть немного красоты и счастья перейдёт из ваших рук к дорогому вам человеку."]});

